def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v != 1}
    # The most numerous colored object is the stencil.
    counts = {c: sum(v == c for row in grid for v in row) for c in colors}
    template_color = max(colors, key=lambda c: counts[c])
    template = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == template_color]
    out = [row[:] for row in grid]
    for color in colors - {template_color}:
        pts = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == color]
        candidates = []
        for tr, tc in template:
            for pr, pc in pts:
                dr, dc = pr - tr, pc - tc
                if all((r - dr, c - dc) in template for r, c in pts):
                    candidates.append((dr, dc))
        if candidates:
            # Every aligned anchor set produces the same full stencil; choose the candidate
            # with the smallest translated stencil row-major if ambiguity remains.
            dr, dc = min(set(candidates), key=lambda x: (x[0], x[1]))
            for r, c in template:
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = color
    return out
